import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
const registry = JSON.parse(readFileSync('deployments/bsc-mainnet.json', 'utf8'));
const snapshot = JSON.parse(readFileSync('verification/bsc-snapshot.json', 'utf8'));
const lines = [
  '# Deployment evidence index', '',
  '<!-- Generated by npm run docs:generate. Edit the registry and evidence, then regenerate. -->', '',
  `Network: **${registry.network}**, chain ID **${registry.chainId}**.`, '',
  `Recorded source baseline: [\`${registry.provenance.baselineCommit}\`](https://github.com/ArexAiData/arexai-contracts/tree/${registry.provenance.baselineCommit}).`, '',
  `Offline creation/runtime evidence: BSC snapshot block **${snapshot.blockNumber}**. This table does not refresh current chain state or represent an audit.`, '',
  '| Component | Address / explorer | Repository source | Creation transaction | Deployment block | Explorer label | Snapshot build |',
  '| --- | --- | --- | --- | ---: | --- | --- |'
];
for (const entry of registry.contracts) {
  const proof = snapshot.contracts.find(c => c.address === entry.address);
  assert(proof, entry.address);
  const input = JSON.parse(readFileSync(proof.input, 'utf8'));
  const build = `${registry.compiler}; optimizer ${input.settings.optimizer.enabled ? 'on' : 'off'} / ${input.settings.optimizer.runs}; EVM ${input.settings.evmVersion}`;
  lines.push(`| ${entry.name} | [\`${entry.address}\`](${entry.bscscan}) | [\`${entry.source}\`](../${entry.source}) | [\`${entry.deploymentTransactionHash}\`](https://bscscan.com/tx/${entry.deploymentTransactionHash}) | ${entry.deploymentBlock} | ${entry.verification} (historical BscScan) | [${build}](../${proof.input}) |`);
}
lines.push('', '## Integrity and verification scope', '',
  '- Source and artifact SHA-256 values: [machine-readable registry](../deployments/bsc-mainnet.json).',
  '- Full original compiler inputs, constructor arguments, receipts and immutable values: [snapshot](../verification/bsc-snapshot.json).',
  '- `npm run verify:registry` checks repository integrity; `npm run verify:bytecode` reproduces the recorded original builds and current executable templates.',
  '- Round 2 keeps its historical BscScan similar-match label. The separately recorded Sourcify creation/runtime matches are exact; these are distinct statements.',
  '- `ArexAI.sol` and `ArexAITeamVesting.sol` are test-workspace implementations. Deployed token/vesting sources are linked in the table.',
  '- Live staking is recorded separately in [staking-mainnet.json](../deployments/staking-mainnet.json), with frozen compiler input and exact creation/runtime evidence. See [mainnet verification](STAKING_MAINNET.md). This table retains the original six-contract snapshot.',
  '- [Verification procedure](VERIFICATION.md) and [recipient/pause limitations](RECIPIENT_AND_PAUSE_POLICY.md).', '');
const output = lines.join('\n');
const path = 'docs/DEPLOYMENTS.md';
if (process.argv.includes('--check')) {
  assert.equal(readFileSync(path, 'utf8'), output, 'Deployment table is stale: run npm run docs:generate');
  console.log('Deployment evidence table matches all six registry/snapshot records.');
} else { writeFileSync(path, output); console.log(`Generated ${path}`); }
